     [R(SOMMERVILLE, "Quality Management 장"), R(PRESSMAN, "Quality Concepts, Software Metrics 관련 장"), {"kind": "web", "provider": "ISO", "title": "ISO/IEC 25010 제품 품질 모델", "url": "https://iso25000.com/index.php/en/iso-25000-standards/iso-25010", "lang": "영어"}],
