def verify():
    assert 10 / 50 == 0.2 and 5 + 7 + 11 == 23 and 9 - 7 + 2 == 4 and 30 / 15 == 2 and 12 // 2 == 6
    assert 30000 / 500 == 60 and abs(2.4 * 32 ** 1.05 - 91.3) < 0.1 and max(3 + 4 + 3, 3 + 2 + 3) == 10


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
